import {createRequire} from 'node:module'
import {dirname,join} from 'node:path'
const adapterRequire=createRequire(new URL('../../../../adapters/package.json',import.meta.url))
const baileysLeaf=(leaf:string)=>join(dirname(adapterRequire.resolve('@whiskeysockets/baileys')),leaf)
const signalLeaf=(leaf:string)=>join(dirname(createRequire(adapterRequire.resolve('@whiskeysockets/baileys')).resolve('libsignal/package.json')),'src',leaf)
import {assertDisposableFixtureHome} from '../../../../scripts/quality-gate/go-parity/fixture-guard'
assertDisposableFixtureHome(process.env.HOME,'WhatsApp actual Node Signal peer')
if(process.env.CC_HAHA_WHATSAPP_LEAF!=='1')throw new Error('Unowned original Signal peer')
const input=await Bun.stdin.json()
const {initAuthCreds}=await import(baileysLeaf('Utils/auth-utils.js'))
const {BufferJSON}=await import(baileysLeaf('Utils/generics.js'))
const {makeLibSignalRepository}=await import(baileysLeaf('Signal/libsignal.js'))
const req=createRequire(import.meta.url),curve=req(signalLeaf('curve.js'))
console.info=()=>{};console.warn=()=>{};console.error=()=>{}
function peer(creds:any,values:any){const keys={async get(type:string,ids:string[]){const result:any={};for(const id of ids)result[id]=values[type]?.[id]??null;return result},async set(updates:any){for(const type of Object.keys(updates)){values[type]??={};for(const [id,value]of Object.entries(updates[type])){if(value)values[type][id]=value;else delete values[type][id]}}},async transaction(f:any){return await f()}};const repo=makeLibSignalRepository({creds,keys}as any,{trace(){},debug(){},info(){},warn(){},error(){}}as any);return{creds,values,repo}}
const prefix=(p:Buffer)=>Buffer.concat([Buffer.from([5]),p])
let a:any,b:any,packets:any[]=[],plain:any[]=[]
if(input.op==='setup'){a=peer(initAuthCreds(),{});b=peer(initAuthCreds(),{});await a.repo.injectE2ESession({jid:'222@s.whatsapp.net',session:{registrationId:b.creds.registrationId,identityKey:prefix(b.creds.signedIdentityKey.public),signedPreKey:{keyId:b.creds.signedPreKey.keyId,publicKey:prefix(b.creds.signedPreKey.keyPair.public),signature:b.creds.signedPreKey.signature}}});const first=await a.repo.encryptMessage({jid:'222@s.whatsapp.net',data:Buffer.from('private-prime')});plain.push((await b.repo.decryptMessage({jid:'111@s.whatsapp.net',type:first.type,ciphertext:first.ciphertext})).toString());const ack=await b.repo.encryptMessage({jid:'111@s.whatsapp.net',data:Buffer.from('private-prime-ack')});plain.push((await a.repo.decryptMessage({jid:'222@s.whatsapp.net',type:ack.type,ciphertext:ack.ciphertext})).toString());for(let i=0;i<5;i++){const p=await a.repo.encryptMessage({jid:'222@s.whatsapp.net',data:Buffer.from('NODE_MESSAGE_'+i)});packets.push({type:p.type,ciphertext:p.ciphertext})}}
else{a=peer(JSON.parse(JSON.stringify(input.a.creds),BufferJSON.reviver),JSON.parse(JSON.stringify(input.a.values),BufferJSON.reviver));b=peer(JSON.parse(JSON.stringify(input.b.creds),BufferJSON.reviver),JSON.parse(JSON.stringify(input.b.values),BufferJSON.reviver));for(const p of input.replies){plain.push((await a.repo.decryptMessage({jid:'222@s.whatsapp.net',type:p.type,ciphertext:Buffer.from(p.ciphertext,'base64')})).toString())};if(input.rekey){await a.repo.injectE2ESession({jid:'222@s.whatsapp.net',session:{registrationId:b.creds.registrationId,identityKey:prefix(b.creds.signedIdentityKey.public),signedPreKey:{keyId:b.creds.signedPreKey.keyId,publicKey:prefix(b.creds.signedPreKey.keyPair.public),signature:b.creds.signedPreKey.signature}}});const init=await a.repo.encryptMessage({jid:'222@s.whatsapp.net',data:Buffer.from('private-rekey')});plain.push((await b.repo.decryptMessage({jid:'111@s.whatsapp.net',type:init.type,ciphertext:init.ciphertext})).toString());const ack=await b.repo.encryptMessage({jid:'111@s.whatsapp.net',data:Buffer.from('private-rekey-ack')});plain.push((await a.repo.decryptMessage({jid:'222@s.whatsapp.net',type:ack.type,ciphertext:ack.ciphertext})).toString())};for(let i=0;i<5;i++){const p=await a.repo.encryptMessage({jid:'222@s.whatsapp.net',data:Buffer.from('NODE_RATCHET_'+input.round+'_'+i)});packets.push({type:p.type,ciphertext:p.ciphertext})}}
process.stdout.write(JSON.stringify({a:{creds:a.creds,values:a.values},b:{creds:b.creds,values:b.values},packets,plain},BufferJSON.replacer)+'\n')
